);

-- table participant_reviews
CREATE TABLE participant_reviews (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES profiles(id),role TEXT NOT NULL,property_id TEXT REFERENCES properties(id),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),method TEXT NOT NULL DEFAULT '',reference TEXT NOT NULL DEFAULT '',reviewer_id TEXT,notes TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,reviewed_at INTEGER,valid_until INTEGER,version INTEGER NOT NULL DEFAULT 1, property_revision INTEGER NOT NULL DEFAULT 0);

-- table payment_intents
CREATE TABLE payment_intents (
 id TEXT PRIMARY KEY,booking_id TEXT NOT NULL REFERENCES bookings(id),user_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('payment','deposit')),
 amount INTEGER NOT NULL CHECK(amount>0),currency TEXT NOT NULL DEFAULT 'KZT',status TEXT NOT NULL DEFAULT 'prepared' CHECK(status IN ('prepared','processing','ready','paid','failed')),
 checkout_url TEXT NOT NULL DEFAULT '',provider_reference TEXT NOT NULL DEFAULT '',request_key TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(user_id,request_key)
);

-- table phone_verifications
CREATE TABLE phone_verifications (user_id TEXT PRIMARY KEY,phone TEXT NOT NULL,code_hash TEXT NOT NULL,expires_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,sent_at INTEGER NOT NULL,verified_at INTEGER);

-- table pilot_policy
CREATE TABLE pilot_policy (
 id TEXT PRIMARY KEY CHECK(id='global'),
 require_owner_review INTEGER NOT NULL DEFAULT 0 CHECK(require_owner_review IN (0,1)),
 require_cleaner_review INTEGER NOT NULL DEFAULT 0 CHECK(require_cleaner_review IN (0,1)),
 require_phone INTEGER NOT NULL DEFAULT 0 CHECK(require_phone IN (0,1)),
 version INTEGER NOT NULL DEFAULT 1, updated_by TEXT NOT NULL DEFAULT '',updated_at INTEGER NOT NULL DEFAULT 0
);

-- table profile_details
CREATE TABLE profile_details (
 user_id TEXT PRIMARY KEY REFERENCES profiles(id) ON DELETE CASCADE,
 avatar_id TEXT, work_status TEXT NOT NULL DEFAULT 'available',
 version INTEGER NOT NULL DEFAULT 1, revision TEXT NOT NULL, updated_at INTEGER NOT NULL
);

-- table profile_preferences
CREATE TABLE profile_preferences (
 user_id TEXT PRIMARY KEY REFERENCES profiles(id),bio TEXT NOT NULL DEFAULT '',languages TEXT NOT NULL DEFAULT '',
 avatar_visibility TEXT NOT NULL DEFAULT 'participants' CHECK(avatar_visibility IN ('participants','self')),
 show_presence INTEGER NOT NULL DEFAULT 1 CHECK(show_presence IN (0,1)),
 show_receipts INTEGER NOT NULL DEFAULT 1 CHECK(show_receipts IN (0,1))
);

-- table profiles
CREATE TABLE `profiles` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`contact` text DEFAULT '' NOT NULL,
	`city` text DEFAULT 'Павлодар' NOT NULL,
	`roles` text DEFAULT '["guest"]' NOT NULL,
	`districts` text DEFAULT '' NOT NULL,
	`experience` text DEFAULT '' NOT NULL,
	`availability` text DEFAULT '' NOT NULL,
	`created_at` integer NOT NULL
);

-- table properties
CREATE TABLE `properties` (
	`id` text PRIMARY KEY NOT NULL,
	`owner_id` text NOT NULL,
	`demo_owner` text,
	`title` text NOT NULL,
	`city` text NOT NULL,
	`district` text NOT NULL,
	`address` text NOT NULL,
	`description` text NOT NULL,
	`price` integer NOT NULL,
	`rooms` integer NOT NULL,
	`capacity` integer NOT NULL,
	`cleaning_minutes` integer DEFAULT 90 NOT NULL,
	`published` integer DEFAULT 1 NOT NULL,
	`created_at` integer NOT NULL
);

-- table property_access
CREATE TABLE property_access (property_id TEXT PRIMARY KEY REFERENCES properties(id),ciphertext TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,updated_at INTEGER NOT NULL);

-- table property_details
CREATE TABLE property_details (
 property_id TEXT PRIMARY KEY REFERENCES properties(id) ON DELETE CASCADE,
 details TEXT NOT NULL DEFAULT '{}', photos TEXT NOT NULL DEFAULT '[]',
 version INTEGER NOT NULL DEFAULT 1, revision TEXT NOT NULL, updated_at INTEGER NOT NULL
);

-- table property_import_links
CREATE TABLE property_import_links (
 owner_id TEXT NOT NULL REFERENCES profiles(id),source TEXT NOT NULL,external_id TEXT NOT NULL,
 address_key TEXT NOT NULL,property_id TEXT NOT NULL UNIQUE REFERENCES properties(id),created_at INTEGER NOT NULL,
 PRIMARY KEY(owner_id,source,external_id),UNIQUE(owner_id,address_key)
);

-- table property_imports
CREATE TABLE property_imports (
 id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES profiles(id),source TEXT NOT NULL,
 payload_hash TEXT NOT NULL,rows_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'prepared' CHECK(status IN ('prepared','committed')),
 version INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,
 commit_hash TEXT,result TEXT
);

-- table property_locations
CREATE TABLE property_locations (
 property_id TEXT PRIMARY KEY REFERENCES properties(id) ON DELETE CASCADE,
 longitude REAL NOT NULL CHECK(longitude BETWEEN -180 AND 180),
 latitude REAL NOT NULL CHECK(latitude BETWEEN -85 AND 85),
 source TEXT NOT NULL CHECK(source IN ('owner','fixture')),
 address_fingerprint TEXT NOT NULL,
 version INTEGER NOT NULL DEFAULT 1,
 updated_at INTEGER NOT NULL
);

-- table property_operations
CREATE TABLE property_operations (
 property_id TEXT PRIMARY KEY REFERENCES properties(id),
 readiness TEXT NOT NULL DEFAULT 'inspection' CHECK(readiness IN ('ready','occupied','awaiting_cleaning','cleaning','inspection','maintenance','blocked')),
 active_booking_id TEXT REFERENCES bookings(id),
 version INTEGER NOT NULL DEFAULT 1,
 note TEXT NOT NULL DEFAULT '',
 updated_at INTEGER NOT NULL
);

-- table property_policies
CREATE TABLE property_policies (
 property_id TEXT PRIMARY KEY REFERENCES properties(id),
 hourly_price INTEGER NOT NULL DEFAULT 0 CHECK(hourly_price>=0),
 min_hours INTEGER NOT NULL DEFAULT 2 CHECK(min_hours BETWEEN 1 AND 24),
 nightly_price INTEGER NOT NULL DEFAULT 0 CHECK(nightly_price>=0),
 checkin_minutes INTEGER NOT NULL DEFAULT 840 CHECK(checkin_minutes BETWEEN 0 AND 1439),
 checkout_minutes INTEGER NOT NULL DEFAULT 720 CHECK(checkout_minutes BETWEEN 0 AND 1439),
 deposit INTEGER NOT NULL DEFAULT 0 CHECK(deposit>=0),
 house_rules TEXT NOT NULL DEFAULT '',
 auto_confirm INTEGER NOT NULL DEFAULT 0 CHECK(auto_confirm IN (0,1)),
 cleaning_fee INTEGER NOT NULL DEFAULT 0 CHECK(cleaning_fee>=0),
 cleaning_budget INTEGER NOT NULL DEFAULT 0 CHECK(cleaning_budget>=cleaning_fee),
 version INTEGER NOT NULL DEFAULT 1,
 revision TEXT NOT NULL,
 updated_at INTEGER NOT NULL
, max_discount_percent INTEGER NOT NULL DEFAULT 0 CHECK(max_discount_percent BETWEEN 0 AND 50), minimum_rate INTEGER NOT NULL DEFAULT 0 CHECK(minimum_rate>=0), repair_budget INTEGER NOT NULL DEFAULT 0 CHECK(repair_budget>=0), auto_extension INTEGER NOT NULL DEFAULT 0 CHECK(auto_extension IN (0,1)), max_extension_hours INTEGER NOT NULL DEFAULT 0 CHECK(max_extension_hours BETWEEN 0 AND 168), mandate_until INTEGER NOT NULL DEFAULT 0, escalation_contact TEXT NOT NULL DEFAULT '', auto_assign INTEGER NOT NULL DEFAULT 0 CHECK(auto_assign IN (0,1)));

-- table provider_events
CREATE TABLE provider_events (provider TEXT NOT NULL,event_id TEXT NOT NULL,intent_id TEXT NOT NULL,payload_hash TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(provider,event_id));

-- table review_property_bindings
