-- table worker_dispatch
CREATE TABLE worker_dispatch (user_id TEXT PRIMARY KEY REFERENCES profiles(id),receive_offers INTEGER NOT NULL DEFAULT 0 CHECK(receive_offers IN (0,1)),updated_at INTEGER NOT NULL);

