-- trigger booking_calendar_freshness_insert
CREATE TRIGGER booking_calendar_freshness_insert BEFORE INSERT ON bookings WHEN NEW.status='confirmed' OR (NEW.status='requested' AND NEW.expires_at>unixepoch()) BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM calendar_sources WHERE property_id=NEW.property_id AND enabled=1 AND url<>'' AND (last_success IS NULL OR last_success<unixepoch()-3600 OR last_error<>'')) THEN RAISE(ABORT,'external_calendar_stale') END;
END;

-- trigger booking_calendar_freshness_update
CREATE TRIGGER booking_calendar_freshness_update BEFORE UPDATE OF start,end,occupied_until,status ON bookings WHEN NEW.status='confirmed' OR (NEW.status='requested' AND NEW.expires_at>unixepoch()) BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM calendar_sources WHERE property_id=NEW.property_id AND enabled=1 AND url<>'' AND (last_success IS NULL OR last_success<unixepoch()-3600 OR last_error<>'')) THEN RAISE(ABORT,'external_calendar_stale') END;
END;

-- trigger booking_external_insert
CREATE TRIGGER booking_external_insert BEFORE INSERT ON bookings WHEN NEW.status='confirmed' OR (NEW.status='requested' AND NEW.expires_at>unixepoch()) BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM external_blocks x JOIN calendar_sources s ON s.id=x.source_id WHERE x.property_id=NEW.property_id AND s.enabled=1 AND x.start<NEW.occupied_until AND x.end>NEW.start) THEN RAISE(ABORT,'external_calendar_overlap') END;
END;

-- trigger booking_external_update
CREATE TRIGGER booking_external_update BEFORE UPDATE OF start,end,occupied_until,status ON bookings WHEN NEW.status='confirmed' OR (NEW.status='requested' AND NEW.expires_at>unixepoch()) BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM external_blocks x JOIN calendar_sources s ON s.id=x.source_id WHERE x.property_id=NEW.property_id AND s.enabled=1 AND x.start<NEW.occupied_until AND x.end>NEW.start) THEN RAISE(ABORT,'external_calendar_overlap') END;
END;

-- trigger booking_insert_guard
CREATE TRIGGER booking_insert_guard BEFORE INSERT ON bookings BEGIN
  SELECT CASE WHEN NEW.end <= NEW.start OR NEW.occupied_until < NEW.end OR NEW.amount < 0 OR NEW.guests < 1 OR NEW.status NOT IN ('requested','confirmed','cancelled','expired','completed') THEN RAISE(ABORT, 'invalid_booking') END;
  SELECT CASE WHEN (NEW.status='confirmed' OR (NEW.status='requested' AND NEW.expires_at>unixepoch())) AND EXISTS (
    SELECT 1 FROM bookings b WHERE b.property_id=NEW.property_id
    AND (b.status='confirmed' OR (b.status='requested' AND b.expires_at>unixepoch()))
    AND b.start<NEW.occupied_until AND b.occupied_until>NEW.start
  ) THEN RAISE(ABORT, 'booking_overlap') END;
  SELECT CASE WHEN (NEW.status='confirmed' OR (NEW.status='requested' AND NEW.expires_at>unixepoch())) AND EXISTS (
    SELECT 1 FROM cleaning_jobs j WHERE j.property_id=NEW.property_id AND j.status IN ('open','assigned','in_progress','submitted') AND (j.booking_id IS NULL OR j.booking_id<>NEW.id) AND j.start<NEW.occupied_until AND j.end>NEW.start
  ) THEN RAISE(ABORT, 'booking_overlap') END;
END;

-- trigger booking_update_cleaning_guard
CREATE TRIGGER booking_update_cleaning_guard BEFORE UPDATE OF start,end,occupied_until,status ON bookings
WHEN NEW.status='confirmed' OR (NEW.status='requested' AND NEW.expires_at>unixepoch()) BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM cleaning_jobs j WHERE j.property_id=NEW.property_id AND j.status IN ('open','assigned','in_progress','submitted') AND (j.booking_id IS NULL OR j.booking_id<>NEW.id) AND j.start<NEW.occupied_until AND j.end>NEW.start) THEN RAISE(ABORT,'booking_overlap') END;
END;

-- trigger booking_update_guard
CREATE TRIGGER booking_update_guard BEFORE UPDATE ON bookings BEGIN
  SELECT CASE WHEN NEW.end <= NEW.start OR NEW.occupied_until < NEW.end OR NEW.status NOT IN ('requested','confirmed','cancelled','expired','completed') THEN RAISE(ABORT, 'invalid_booking') END;
  SELECT CASE WHEN (NEW.status='confirmed' OR (NEW.status='requested' AND NEW.expires_at>unixepoch())) AND EXISTS (
    SELECT 1 FROM bookings b WHERE b.id<>NEW.id AND b.property_id=NEW.property_id
    AND (b.status='confirmed' OR (b.status='requested' AND b.expires_at>unixepoch()))
    AND b.start<NEW.occupied_until AND b.occupied_until>NEW.start
  ) THEN RAISE(ABORT, 'booking_overlap') END;
END;

-- trigger cleaner_assignment_guard
CREATE TRIGGER cleaner_assignment_guard BEFORE UPDATE OF assigned_to,status,start,end ON cleaning_jobs
WHEN NEW.assigned_to IS NOT NULL AND NEW.status IN ('assigned','in_progress','submitted') BEGIN
  SELECT CASE WHEN EXISTS (SELECT 1 FROM cleaning_jobs j WHERE j.id<>NEW.id AND j.assigned_to=NEW.assigned_to AND j.status IN ('assigned','in_progress','submitted') AND j.start<NEW.end AND j.end>NEW.start) THEN RAISE(ABORT, 'cleaner_overlap') END;
END;

-- trigger cleaning_job_completed
CREATE TRIGGER cleaning_job_completed AFTER UPDATE OF status ON cleaning_jobs
WHEN NEW.status='completed' AND OLD.status='submitted'
BEGIN UPDATE cleaning_jobs SET completed_at=unixepoch() WHERE id=NEW.id; END;

-- trigger cleaning_job_revision
CREATE TRIGGER cleaning_job_revision AFTER UPDATE OF status,start,end,fee,assigned_to,checklist,report ON cleaning_jobs
BEGIN UPDATE cleaning_jobs SET version=OLD.version+1 WHERE id=NEW.id; END;

-- trigger cleaning_job_revision_requested
CREATE TRIGGER cleaning_job_revision_requested AFTER UPDATE OF status ON cleaning_jobs
WHEN NEW.status='in_progress' AND OLD.status='submitted'
BEGIN UPDATE cleaning_jobs SET submitted_at=NULL,completed_at=NULL WHERE id=NEW.id; END;

-- trigger cleaning_job_started
CREATE TRIGGER cleaning_job_started AFTER UPDATE OF status ON cleaning_jobs
WHEN NEW.status='in_progress' AND OLD.status='assigned'
BEGIN UPDATE cleaning_jobs SET started_at=COALESCE(started_at,unixepoch()) WHERE id=NEW.id; END;

-- trigger cleaning_job_submitted
CREATE TRIGGER cleaning_job_submitted AFTER UPDATE OF status ON cleaning_jobs
WHEN NEW.status='submitted' AND OLD.status='in_progress'
BEGIN UPDATE cleaning_jobs SET submitted_at=unixepoch() WHERE id=NEW.id; END;

-- trigger cleaning_property_interval_insert
CREATE TRIGGER cleaning_property_interval_insert BEFORE INSERT ON cleaning_jobs WHEN NEW.status IN ('open','assigned','in_progress','submitted') BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM bookings b WHERE b.property_id=NEW.property_id AND (NEW.booking_id IS NULL OR b.id<>NEW.booking_id) AND (b.status='confirmed' OR (b.status='requested' AND b.expires_at>unixepoch())) AND b.start<NEW.end AND b.occupied_until>NEW.start) THEN RAISE(ABORT,'booking_overlap') END;
END;

-- trigger cleaning_requires_vacancy
CREATE TRIGGER cleaning_requires_vacancy BEFORE UPDATE OF status ON cleaning_jobs
WHEN NEW.status='in_progress' AND OLD.status<>'in_progress' BEGIN
 SELECT CASE WHEN NEW.booking_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM bookings WHERE id=NEW.booking_id AND status='completed') THEN RAISE(ABORT,'checkout_required') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM property_operations WHERE property_id=NEW.property_id AND (active_booking_id IS NOT NULL OR readiness IN ('occupied','maintenance','blocked'))) THEN RAISE(ABORT,'property_not_vacant') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM cleaning_jobs WHERE property_id=NEW.property_id AND id<>NEW.id AND status IN ('in_progress','submitted')) THEN RAISE(ABORT,'property_cleaning_busy') END;
END;

-- trigger discussion_message_notification
CREATE TRIGGER discussion_message_notification AFTER INSERT ON discussion_messages BEGIN
 INSERT OR IGNORE INTO notifications(id,user_id,body,dedupe,read,created_at)
 SELECT lower(hex(randomblob(16))),json_extract(m.value,'$.id'),
 'Новое сообщение в обсуждении процесса. Откройте чат участников.',
 json_extract(m.value,'$.role')||':discussion:'||NEW.room_id||':'||NEW.seq,0,NEW.created_at
 FROM discussion_rooms r,json_each(r.members) m
 WHERE r.id=NEW.room_id AND json_extract(m.value,'$.id')<>NEW.sender_id;
END;

-- trigger finance_no_delete
CREATE TRIGGER finance_no_delete BEFORE DELETE ON finance_entries BEGIN SELECT RAISE(ABORT,'immutable_finance_entry'); END;

-- trigger finance_no_update
CREATE TRIGGER finance_no_update BEFORE UPDATE ON finance_entries BEGIN SELECT RAISE(ABORT,'immutable_finance_entry'); END;

-- trigger journey_assignment_revoked
CREATE TRIGGER journey_assignment_revoked AFTER UPDATE OF assigned_to,status,owner_id ON cleaning_jobs
WHEN NEW.status<>'assigned' OR OLD.assigned_to IS NOT NEW.assigned_to OR OLD.owner_id<>NEW.owner_id
BEGIN UPDATE journey_sessions SET stopped_at=CAST(strftime('%s','now') AS INTEGER),longitude=NULL,latitude=NULL,accuracy=NULL WHERE entity_kind='job' AND entity_id=NEW.id AND stopped_at IS NULL; END;

-- trigger journey_booking_revoked
CREATE TRIGGER journey_booking_revoked AFTER UPDATE OF status,guest_id ON bookings
WHEN NEW.status<>'confirmed' OR OLD.guest_id<>NEW.guest_id
BEGIN UPDATE journey_sessions SET stopped_at=CAST(strftime('%s','now') AS INTEGER),longitude=NULL,latitude=NULL,accuracy=NULL WHERE entity_kind='booking' AND entity_id=NEW.id AND stopped_at IS NULL; END;

-- trigger journey_checkin_finished
CREATE TRIGGER journey_checkin_finished AFTER UPDATE OF actual_checkin,actual_checkout ON booking_terms
WHEN NEW.actual_checkin IS NOT NULL OR NEW.actual_checkout IS NOT NULL
BEGIN UPDATE journey_sessions SET stopped_at=CAST(strftime('%s','now') AS INTEGER),longitude=NULL,latitude=NULL,accuracy=NULL WHERE entity_kind='booking' AND entity_id=NEW.booking_id AND stopped_at IS NULL; END;

-- trigger journey_owner_changed
CREATE TRIGGER journey_owner_changed AFTER UPDATE OF owner_id ON properties
WHEN OLD.owner_id<>NEW.owner_id
BEGIN UPDATE journey_sessions SET stopped_at=CAST(strftime('%s','now') AS INTEGER),longitude=NULL,latitude=NULL,accuracy=NULL WHERE stopped_at IS NULL AND ((entity_kind='booking' AND entity_id IN (SELECT id FROM bookings WHERE property_id=NEW.id)) OR (entity_kind='job' AND entity_id IN (SELECT id FROM cleaning_jobs WHERE property_id=NEW.id))); END;

-- trigger journey_route_erased
CREATE TRIGGER journey_route_erased AFTER UPDATE OF stopped_at,longitude,latitude ON journey_sessions
WHEN NEW.stopped_at IS NOT NULL OR NEW.longitude IS NULL OR NEW.latitude IS NULL
BEGIN UPDATE journey_sessions SET route=NULL,route_recorded_at=NULL WHERE id=NEW.id; END;

-- trigger notification_outbox
CREATE TRIGGER notification_outbox AFTER INSERT ON notifications BEGIN
 INSERT OR IGNORE INTO delivery_outbox(id,notification_id,user_id,role,channel,available_at,created_at)
 SELECT lower(hex(randomblob(16))),NEW.id,NEW.user_id,c.role,c.channel,NEW.created_at,NEW.created_at FROM delivery_channels c
 WHERE c.user_id=NEW.user_id AND c.enabled=1 AND c.verified_at IS NOT NULL AND NEW.dedupe LIKE c.role||':%';
END;

-- trigger pilot_booking_insert
CREATE TRIGGER pilot_booking_insert BEFORE INSERT ON bookings WHEN NEW.status IN ('requested','confirmed') AND EXISTS(SELECT 1 FROM properties WHERE id=NEW.property_id AND demo_owner IS NULL) BEGIN
 SELECT CASE WHEN (SELECT require_owner_review FROM pilot_policy WHERE id='global')=1 AND NOT EXISTS(SELECT 1 FROM pilot_property_admissions WHERE id=NEW.property_id AND owner_reviewed=1)
  THEN RAISE(ABORT,'pilot_owner_review_required') END;
 SELECT CASE WHEN (SELECT require_phone FROM pilot_policy WHERE id='global')=1 AND
  (NOT EXISTS(SELECT 1 FROM pilot_property_admissions WHERE id=NEW.property_id AND owner_phone_verified=1) OR NOT EXISTS(SELECT 1 FROM phone_verifications WHERE user_id=NEW.guest_id AND verified_at IS NOT NULL))
  THEN RAISE(ABORT,'pilot_phone_required') END;
END;

-- trigger pilot_booking_update
CREATE TRIGGER pilot_booking_update BEFORE UPDATE OF status,start,end ON bookings WHEN NEW.status IN ('requested','confirmed') AND EXISTS(SELECT 1 FROM properties WHERE id=NEW.property_id AND demo_owner IS NULL) BEGIN
 SELECT CASE WHEN (SELECT require_owner_review FROM pilot_policy WHERE id='global')=1 AND NOT EXISTS(SELECT 1 FROM pilot_property_admissions WHERE id=NEW.property_id AND owner_reviewed=1)
  THEN RAISE(ABORT,'pilot_owner_review_required') END;
 SELECT CASE WHEN (SELECT require_phone FROM pilot_policy WHERE id='global')=1 AND
  (NOT EXISTS(SELECT 1 FROM pilot_property_admissions WHERE id=NEW.property_id AND owner_phone_verified=1) OR NOT EXISTS(SELECT 1 FROM phone_verifications WHERE user_id=NEW.guest_id AND verified_at IS NOT NULL))
  THEN RAISE(ABORT,'pilot_phone_required') END;
END;

-- trigger pilot_cleaner_assignment
CREATE TRIGGER pilot_cleaner_assignment BEFORE UPDATE OF assigned_to ON cleaning_jobs WHEN NEW.assigned_to IS NOT NULL AND (OLD.assigned_to IS NULL OR OLD.assigned_to<>NEW.assigned_to) AND EXISTS(SELECT 1 FROM properties WHERE id=NEW.property_id AND demo_owner IS NULL) BEGIN
 SELECT CASE WHEN (SELECT require_cleaner_review FROM pilot_policy WHERE id='global')=1 AND NOT EXISTS(SELECT 1 FROM pilot_worker_admissions WHERE id=NEW.assigned_to AND cleaner_reviewed=1)
  THEN RAISE(ABORT,'pilot_cleaner_review_required') END;
 SELECT CASE WHEN (SELECT require_phone FROM pilot_policy WHERE id='global')=1 AND NOT EXISTS(SELECT 1 FROM pilot_worker_admissions WHERE id=NEW.assigned_to AND phone_verified=1)
  THEN RAISE(ABORT,'pilot_phone_required') END;
END;

-- trigger pilot_property_publish_insert
CREATE TRIGGER pilot_property_publish_insert BEFORE INSERT ON properties WHEN NEW.published=1 AND NEW.demo_owner IS NULL BEGIN
 SELECT CASE WHEN (SELECT require_owner_review FROM pilot_policy WHERE id='global')=1
  THEN RAISE(ABORT,'pilot_owner_review_required') END;
 SELECT CASE WHEN (SELECT require_phone FROM pilot_policy WHERE id='global')=1 AND NOT EXISTS(SELECT 1 FROM phone_verifications WHERE user_id=NEW.owner_id AND verified_at IS NOT NULL)
  THEN RAISE(ABORT,'pilot_phone_required') END;
END;

-- trigger pilot_property_publish_update
CREATE TRIGGER pilot_property_publish_update BEFORE UPDATE OF published,owner_id ON properties WHEN NEW.published=1 AND NEW.demo_owner IS NULL BEGIN
 SELECT CASE WHEN (SELECT require_owner_review FROM pilot_policy WHERE id='global')=1 AND NOT EXISTS(SELECT 1 FROM pilot_property_admissions a WHERE a.id=NEW.id AND a.owner_id=NEW.owner_id AND a.owner_reviewed=1)
  THEN RAISE(ABORT,'pilot_owner_review_required') END;
 SELECT CASE WHEN (SELECT require_phone FROM pilot_policy WHERE id='global')=1 AND NOT EXISTS(SELECT 1 FROM phone_verifications WHERE user_id=NEW.owner_id AND verified_at IS NOT NULL)
  THEN RAISE(ABORT,'pilot_phone_required') END;
END;

-- trigger property_location_address_changed
CREATE TRIGGER property_location_address_changed AFTER UPDATE OF address,city,district ON properties
WHEN OLD.address<>NEW.address OR OLD.city<>NEW.city OR OLD.district<>NEW.district
BEGIN DELETE FROM property_locations WHERE property_id=NEW.id; END;

-- trigger review_bind_property_request
CREATE TRIGGER review_bind_property_request AFTER INSERT ON participant_reviews
 WHEN NEW.role='owner' AND NEW.property_id IS NOT NULL BEGIN
 UPDATE participant_reviews SET property_revision=COALESCE((SELECT revision FROM review_property_bindings WHERE property_id=NEW.property_id),0) WHERE id=NEW.id;
END;

-- trigger review_property_material_change
CREATE TRIGGER review_property_material_change AFTER UPDATE OF city,district,address,owner_id ON properties
 WHEN OLD.city<>NEW.city OR OLD.district<>NEW.district OR OLD.address<>NEW.address OR OLD.owner_id<>NEW.owner_id BEGIN
 INSERT INTO review_property_bindings(property_id,revision) VALUES (NEW.id,1)
 ON CONFLICT(property_id) DO UPDATE SET revision=revision+1;
END;

-- trigger review_reject_stale_approval
CREATE TRIGGER review_reject_stale_approval BEFORE UPDATE OF status ON participant_reviews
 WHEN NEW.role='owner' AND NEW.property_id IS NOT NULL AND NEW.status='approved' BEGIN
 SELECT CASE WHEN NEW.property_revision<>COALESCE((SELECT revision FROM review_property_bindings WHERE property_id=NEW.property_id),0)
 OR NOT EXISTS(SELECT 1 FROM properties WHERE id=NEW.property_id AND owner_id=NEW.user_id)
 THEN RAISE(ABORT,'pilot_review_stale') END;
END;
